def split_row(line: str):
    """Split one CSV line into fields, honoring quoted commas and quotes."""
    fields = []
    field = []
    in_quotes = False
    index = 0

    while index < len(line):
        char = line[index]
        if in_quotes:
            if char == '"':
                if index + 1 < len(line) and line[index + 1] == '"':
                    field.append('"')
                    index += 2
                    continue
                in_quotes = False
            else:
                field.append(char)
        elif char == '"':
            in_quotes = True
        elif char == ',':
            fields.append(''.join(field))
            field = []
        else:
            field.append(char)
        index += 1

    fields.append(''.join(field))
    return fields
